def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Normalize the number of containers in the stack
    normalized_SH = SH / 10.0
    # Normalize the available space in the stack
    normalized_EMP = EMP / 10.0
    # Normalize the density of future retrievals in the stack
    if SH > 0:
        future_density = RI / (SH + 1)
    else:
        future_density = 0.0
    # Temporal Blocking: prefer stacks with an average ID lower than the current container
    if SH > 0:
        temporal_blocking = (CUR - AVG) / 1000000.0
    else:
        temporal_blocking = 0.0
    # Normalize the temporal adjustment based on the minimum ID difference
    if DIFF > 0:
        temporal_adjustment = 1.0 / (DIFF / 1e9)
    else:
        temporal_adjustment = 0.0
    # Adaptive flow significance: combine temporal and spatial efficiency
    if SH > 0 and AVG < CUR:
        flow_significance = (CUR - AVG) / 100000.0
    else:
        flow_significance = 0.0
    # Compute a refined weighted score that combines density, space, blocking, and adjustment
    priority = future_density * 1.6 - normalized_EMP * 1.2 + normalized_SH * 0.5 + temporal_blocking * 0.8 - temporal_adjustment * 0.04 + flow_significance * 0.4
    return priority
